package org.telegram.messenger.purple;import org.telegram.messenger.UserConfig;public final class PurpleAccountFiles {public static final class Identity {public final int slot;public final String key;public final long lifetime;Identity(int s){slot=s;UserConfig c=UserConfig.getInstance(s);key="0-"+c.user;lifetime=c.lifetime;}public boolean current(){UserConfig c=UserConfig.getInstance(slot);return c.active&&key.equals("0-"+c.user)&&lifetime==c.lifetime;}}public static Identity capture(int s){return UserConfig.getInstance(s).active?new Identity(s):null;}}
